-- Austria deep-dive ES/DE/FR translations (completing 231). INSERT OR IGNORE.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'B2B voluntario (Peppol/ebInterface) — B2G obligatorio desde 2014', 'Esta página de análisis refleja la orientación pública y las noticias disponibles a principios de agosto de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Se esperaba la propuesta formal de facturación electrónica B2B nacional de Austria para el tercer trimestre de 2026, pero no se había publicado en el momento de redactar esto — confirme el estado actual directamente con el BMF o el RIS antes de basarse en ella.', 'Austria fue uno de los primeros países de la UE en imponer la facturación electrónica B2G, con un requisito federal en vigor desde el 1 de enero de 2014 — años antes que la mayoría de sus pares. El B2B sigue siendo voluntario hoy, pero eso está bajo revisión activa: el Ministerio de Hacienda ha señalado que se avecina un mandato nacional basado en Peppol, con una propuesta formal esperada para el tercer trimestre de 2026, frente a un suelo firme de derecho de la UE de julio de 2030 para el B2B transfronterizo, sea cual sea el resultado.', 'Austria es inusual al aceptar dos formatos genuinamente distintos para la misma obligación B2G: ebInterface, su propio estándar XML nacional de larga trayectoria, y Peppol BIS 3.0. Ambos están alineados con EN 16931 desde ebInterface 5.0, de modo que una empresa capaz de usar cualquiera de los dos está preparada para lo que traiga un futuro mandato B2B nacional.', 'La presentación B2G se realiza a través del USP (Unternehmensserviceportal) — mediante carga web directa en formato ebInterface, o a través de la red Peppol — con un canal heredado EDIAKT II aún disponible para grandes proveedores con conexiones EDI preexistentes. No existe un modelo nacional de compensación o reporte en tiempo real para el B2B, que sigue siendo cuestión de acuerdo bilateral entre las partes comerciales.', 'Con el B2B aún voluntario, la mayor parte del trabajo a corto plazo de las empresas tiene que ver con la preparación más que con el cumplimiento: confirmar la capacidad ebInterface o Peppol, seguir la decisión de alcance del BMF y prepararse para el suelo confirmado de la UE de 2030 para el transfronterizo, sea cual sea el alcance de esa decisión.', 'No existe un régimen sancionador B2B nacional hoy porque no existe un mandato B2B nacional — lo más parecido a la aplicación es el rechazo de facturas B2G por formato no conforme, además del suelo de la UE que se acerca y que se aplica con independencia del calendario propio de Austria.', 'Austria aplica la facturación electrónica B2G obligatoria desde el 1 de enero de 2014 (IKTKonG §5) — uno de los mandatos más tempranos de este tipo en la UE — ampliado en 2018 para cubrir todas las entidades adjudicadoras centrales (BVergG 2018 §368), con varios de sus nueve Länder adoptando requisitos comparables propios. El B2B sigue siendo voluntario. El Ministerio de Hacienda ha indicado que perseguirá un mandato B2B nacional basado en Peppol, siguiendo el ejemplo de Bélgica y los Países Bajos, con una propuesta formal esperada para el tercer trimestre de 2026 — aún no publicada a principios de agosto de 2026. Por separado, el mandato de ViDA de facturación electrónica y reporte transfronterizos B2B es derecho de la UE confirmado desde el 1 de julio de 2030, con independencia del resultado nacional.', '🇦🇹' FROM countries WHERE name_en = 'Austria';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Freiwilliges B2B (Peppol/ebInterface) — B2G verpflichtend seit 2014', 'Diese Länderanalyse spiegelt öffentlich verfügbare Hinweise und Berichterstattung mit Stand Anfang August 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Österreichs formeller Vorschlag zur inländischen B2B-E-Rechnung wurde für das dritte Quartal 2026 erwartet, war aber zum Zeitpunkt der Abfassung noch nicht veröffentlicht — bestätigen Sie den aktuellen Stand direkt beim BMF oder im RIS, bevor Sie darauf aufbauen.', 'Österreich war eines der ersten EU-Länder, das die B2G-E-Rechnung vorschrieb, mit einer bundesweiten Pflicht seit dem 1. Januar 2014 — Jahre vor den meisten Vergleichsländern. B2B bleibt heute freiwillig, wird aber aktiv überprüft: Das Finanzministerium hat eine Peppol-basierte inländische Pflicht signalisiert, mit einem formellen Vorschlag, der für das dritte Quartal 2026 erwartet wird, vor dem Hintergrund einer festen EU-rechtlichen Untergrenze ab Juli 2030 für grenzüberschreitendes B2B, unabhängig vom Ausgang.', 'Österreich ist insofern ungewöhnlich, als es zwei tatsächlich unterschiedliche Formate für dieselbe B2G-Pflicht akzeptiert: ebInterface, den eigenen langjährigen nationalen XML-Standard, und Peppol BIS 3.0. Beide sind seit ebInterface 5.0 an EN 16931 angelehnt, sodass ein zu einem der beiden fähiges Unternehmen für das, was eine künftige inländische B2B-Pflicht bringt, gerüstet ist.', 'Die B2G-Übermittlung läuft über das USP (Unternehmensserviceportal) — entweder als direkter Web-Upload im ebInterface-Format oder über das Peppol-Netzwerk —, wobei ein Legacy-Kanal EDIAKT II für Großlieferanten mit bestehenden EDI-Verbindungen weiterhin verfügbar ist. Es gibt kein inländisches Clearance- oder Echtzeit-Meldemodell für B2B, das weiterhin Sache einer bilateralen Vereinbarung zwischen den Handelspartnern bleibt.', 'Da B2B noch freiwillig ist, geht es bei der kurzfristigen Arbeit der meisten Unternehmen eher um Vorbereitung als um Compliance: ebInterface- oder Peppol-Fähigkeit bestätigen, die Umfangsentscheidung des BMF beobachten und sich auf die bestätigte EU-Untergrenze von 2030 für grenzüberschreitende Geschäfte vorbereiten, unabhängig davon, was diese Entscheidung abdeckt.', 'Es gibt heute kein inländisches B2B-Sanktionsregime, weil es keine inländische B2B-Pflicht gibt — das Nächstliegende an Durchsetzung ist die Ablehnung von B2G-Rechnungen bei nicht konformem Format, zusätzlich zur näherrückenden EU-Untergrenze, die unabhängig vom österreichischen Zeitplan gilt.', 'Österreich betreibt seit dem 1. Januar 2014 (IKTKonG §5) eine verpflichtende B2G-E-Rechnung — eine der frühesten derartigen Pflichten in der EU —, 2018 auf alle zentralen öffentlichen Auftraggeber ausgeweitet (BVergG 2018 §368), wobei mehrere der neun Länder eigene vergleichbare Anforderungen eingeführt haben. B2B bleibt freiwillig. Das Finanzministerium hat angekündigt, eine Peppol-basierte inländische B2B-Pflicht zu verfolgen, analog zu Belgien und den Niederlanden, mit einem formellen Vorschlag, der für das dritte Quartal 2026 erwartet wird — Anfang August 2026 noch nicht veröffentlicht. Unabhängig davon ist ViDAs grenzüberschreitende B2B-E-Rechnungs- und Meldepflicht ab dem 1. Juli 2030 bestätigtes EU-Recht, unabhängig vom inländischen Ausgang.', '🇦🇹' FROM countries WHERE name_en = 'Austria';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'B2B volontaire (Peppol/ebInterface) — B2G obligatoire depuis 2014', 'Cette analyse par pays reflète les informations publiques et l''actualité disponibles début août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. La proposition formelle de facturation électronique B2B nationale de l''Autriche était attendue au troisième trimestre 2026 mais n''avait pas été publiée au moment de la rédaction — confirmez le statut actuel directement auprès du BMF ou du RIS avant de vous y fier.', 'L''Autriche a été l''un des premiers pays de l''UE à imposer la facturation électronique B2G, avec une obligation fédérale en vigueur depuis le 1er janvier 2014 — des années avant la plupart de ses pairs. Le B2B reste volontaire aujourd''hui, mais fait l''objet d''un examen actif : le ministère des Finances a signalé qu''une obligation nationale basée sur Peppol arrivait, avec une proposition formelle attendue au troisième trimestre 2026, face à un plancher ferme de droit de l''UE à partir de juillet 2030 pour le B2B transfrontalier, quelle que soit l''issue.', 'L''Autriche est inhabituelle en ce qu''elle accepte deux formats véritablement distincts pour la même obligation B2G : ebInterface, sa propre norme XML nationale de longue date, et Peppol BIS 3.0. Les deux sont alignés sur l''EN 16931 depuis ebInterface 5.0, si bien qu''une entreprise capable d''utiliser l''un ou l''autre est prête pour ce qu''apportera une future obligation B2B nationale.', 'La soumission B2G se fait via l''USP (Unternehmensserviceportal) — soit par téléversement web direct au format ebInterface, soit via le réseau Peppol —, un canal hérité EDIAKT II restant disponible pour les gros fournisseurs disposant de connexions EDI préexistantes. Il n''existe aucun modèle national de validation préalable ou de déclaration en temps réel pour le B2B, qui reste une question d''accord bilatéral entre partenaires commerciaux.', 'Le B2B étant encore volontaire, l''essentiel du travail à court terme des entreprises relève de la préparation plutôt que de la conformité : confirmer la capacité ebInterface ou Peppol, suivre la décision de périmètre du BMF, et se préparer au plancher confirmé de l''UE de 2030 pour le transfrontalier, quel que soit le périmètre de cette décision.', 'Il n''existe aujourd''hui aucun régime de sanctions B2B national car il n''existe aucune obligation B2B nationale — le mécanisme le plus proche d''une application est le rejet des factures B2G non conformes au format, en plus du plancher de l''UE qui approche et s''applique indépendamment du calendrier propre de l''Autriche.', 'L''Autriche applique la facturation électronique B2G obligatoire depuis le 1er janvier 2014 (IKTKonG §5) — l''une des obligations les plus précoces de ce type dans l''UE —, étendue en 2018 à tous les pouvoirs adjudicateurs centraux (BVergG 2018 §368), plusieurs de ses neuf Länder ayant depuis adopté leurs propres exigences comparables. Le B2B reste volontaire. Le ministère des Finances a indiqué qu''il poursuivrait une obligation B2B nationale basée sur Peppol, à l''instar de la Belgique et des Pays-Bas, une proposition formelle étant attendue au troisième trimestre 2026 — non encore publiée début août 2026. Par ailleurs, l''obligation ViDA de facturation électronique et de déclaration transfrontalières B2B est un droit de l''UE confirmé à partir du 1er juillet 2030, quelle que soit l''issue nationale.', '🇦🇹' FROM countries WHERE name_en = 'Austria';

