INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Estándares aceptados", "ebInterface (6.0/6.1) o Peppol BIS Billing 3.0 — cualquiera es válido para B2G"], ["Base legal", "IKTKonG §5, BGBl. I Nr. 35/2012 (2014); ampliada por la BVergG 2018 §368"], ["Alineación con EN 16931", "Desde ebInterface 5.0; la versión 7.0 (prevista para el 4.º trimestre de 2026) añade una vinculación formal de sintaxis"], ["B2B hoy", "Sin formato obligatorio — tanto Peppol como ebInterface se usan de forma voluntaria"]]', 'A diferencia de la mayoría de este rastreador, Austria no impone un único formato nacional — una empresa ya capaz de usar Peppol para otros mercados de la UE no necesita trabajo de formato adicional para el B2G austriaco, y lo mismo se aplica a la inversa para una implementación exclusiva de ebInterface.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Akzeptierte Standards", "ebInterface (6.0/6.1) oder Peppol BIS Billing 3.0 — beide gültig für B2G"], ["Rechtsgrundlage", "IKTKonG §5, BGBl. I Nr. 35/2012 (2014); erweitert durch BVergG 2018 §368"], ["EN-16931-Angleichung", "Ab ebInterface 5.0; Version 7.0 (erwartet Q4 2026) fügt eine formale Syntaxbindung hinzu"], ["B2B heute", "Kein vorgeschriebenes Format — sowohl Peppol als auch ebInterface werden freiwillig genutzt"]]', 'Anders als bei den meisten Ländern in diesem Tracker erzwingt Österreich kein einziges nationales Format — ein Unternehmen, das bereits Peppol für andere EU-Märkte nutzt, benötigt keine zusätzliche Formatarbeit für das österreichische B2G, und umgekehrt gilt dasselbe für eine reine ebInterface-Implementierung.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Normes acceptées", "ebInterface (6.0/6.1) ou Peppol BIS Billing 3.0 — les deux valables pour le B2G"], ["Base légale", "IKTKonG §5, BGBl. I Nr. 35/2012 (2014) ; étendue par la BVergG 2018 §368"], ["Alignement EN 16931", "Depuis ebInterface 5.0 ; la version 7.0 (attendue au T4 2026) ajoute une liaison syntaxique formelle"], ["B2B aujourd''hui", "Aucun format imposé — Peppol et ebInterface sont tous deux utilisés volontairement"]]', 'Contrairement à la plupart des pays de ce tracker, l''Autriche n''impose pas un format national unique — une entreprise déjà capable d''utiliser Peppol pour d''autres marchés de l''UE n''a besoin d''aucun travail de format supplémentaire pour le B2G autrichien, et inversement pour une implémentation ebInterface uniquement.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores y registro', '[["Registro B2G", "A través del USP (Unternehmensserviceportal), con credenciales de FinanzOnline"], ["Gobernanza del estándar", "ebInterface lo mantiene AUSTRIAPRO, un grupo de trabajo de la WKO (Cámara Federal de Economía austriaca)"], ["Identidad Peppol", "ID de participante Peppol a través de cualquier proveedor de punto de acceso"], ["B2B hoy", "No se requiere registro — acuerdo bilateral entre socios comerciales"]]', 'El paso de registro en el USP es específico para proveedores del gobierno — una empresa que solo comercia B2B de forma voluntaria hoy no tiene ningún registro al que unirse.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kennungen & Registrierung', '[["B2G-Registrierung", "Über das USP (Unternehmensserviceportal), mit FinanzOnline-Zugangsdaten"], ["Standard-Governance", "ebInterface wird von AUSTRIAPRO gepflegt, einem Arbeitskreis der WKO (Wirtschaftskammer Österreich)"], ["Peppol-Identität", "Peppol-Teilnehmer-ID über einen beliebigen Zugangspunktanbieter"], ["B2B heute", "Keine Registrierung erforderlich — bilaterale Vereinbarung zwischen Geschäftspartnern"]]', 'Der USP-Registrierungsschritt betrifft speziell Regierungslieferanten — ein Unternehmen, das heute nur freiwillig B2B handelt, hat überhaupt kein Register, dem es beitreten müsste.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants et enregistrement', '[["Enregistrement B2G", "Via l''USP (Unternehmensserviceportal), avec des identifiants FinanzOnline"], ["Gouvernance de la norme", "ebInterface est maintenue par AUSTRIAPRO, un groupe de travail de la WKO (Chambre économique fédérale autrichienne)"], ["Identité Peppol", "ID de participant Peppol via un fournisseur de point d''accès quelconque"], ["B2B aujourd''hui", "Aucun enregistrement requis — accord bilatéral entre partenaires commerciaux"]]', 'L''étape d''enregistrement à l''USP est spécifique aux fournisseurs du gouvernement — une entreprise qui ne fait que du B2B volontaire aujourd''hui n''a aucun registre auquel adhérer.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio', '[["B2G", "Modelo completo de factura básica EN 16931, en cualquiera de los formatos aceptados"], ["Canal heredado", "EDIAKT II sigue disponible para grandes proveedores con conexiones EDI preexistentes, aunque las nuevas implementaciones deberían usar ebInterface o Peppol"], ["Archivo", "7 años, requisito estándar austriaco de conservación de registros"]]', 'Como ambos formatos aceptados están alineados con EN 16931, los requisitos de datos subyacentes son idénticos independientemente del que elija un proveedor.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalte', '[["B2G", "Vollständiges EN-16931-Kernrechnungsmodell, in beiden akzeptierten Formaten"], ["Legacy-Kanal", "EDIAKT II bleibt für Großlieferanten mit bestehenden EDI-Verbindungen verfügbar, neue Implementierungen sollten jedoch ebInterface oder Peppol nutzen"], ["Archivierung", "7 Jahre, österreichische Standard-Aufbewahrungspflicht"]]', 'Da beide akzeptierten Formate an EN 16931 angelehnt sind, sind die zugrunde liegenden Datenanforderungen unabhängig von der Wahl des Lieferanten identisch.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire', '[["B2G", "Modèle complet de facture de base EN 16931, dans l''un ou l''autre des formats acceptés"], ["Canal hérité", "EDIAKT II reste disponible pour les gros fournisseurs disposant de connexions EDI préexistantes, bien que les nouvelles implémentations doivent utiliser ebInterface ou Peppol"], ["Archivage", "7 ans, exigence standard autrichienne de conservation des documents"]]', 'Les deux formats acceptés étant alignés sur l''EN 16931, les exigences de données sous-jacentes sont identiques quel que soit le choix du fournisseur.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Modelo de red', '[["Modelo B2G", "Carga web directa al USP, o la red de cuatro esquinas de Peppol"], ["Modelo B2B", "Intercambio bilateral voluntario, comúnmente sobre Peppol"], ["Reporte en tiempo real", "Ninguno hoy — Austria no tiene régimen nacional de compensación o CTC"], ["SAF-T", "Existe un sistema bajo demanda desde 2009; un supuesto ''relanzamiento'' de 2024 hacia la presentación periódica sigue sin confirmarse a mediados de 2026"]]', 'Al igual que con los Países Bajos, aquí no hay un modelo de compensación que describir para el B2B — las facturas se mueven directamente entre las partes comerciales, un contraste deliberado con Bélgica, Francia, Italia y Polonia.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Netzwerkmodell', '[["B2G-Modell", "Direkter Web-Upload zum USP oder das Peppol-Vier-Ecken-Netzwerk"], ["B2B-Modell", "Freiwilliger bilateraler Austausch, meist über Peppol"], ["Echtzeit-Meldung", "Heute keine — Österreich hat kein nationales Clearance- oder CTC-Regime"], ["SAF-T", "Ein On-Demand-System besteht seit 2009; ein gemeldeter ''Relaunch'' 2024 hin zu periodischer Meldung bleibt Mitte 2026 unbestätigt"]]', 'Wie bei den Niederlanden gibt es hier kein Clearance-Modell für B2B zu beschreiben — Rechnungen bewegen sich direkt zwischen Handelspartnern, ein bewusster Kontrast zu Belgien, Frankreich, Italien und Polen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Modèle de réseau', '[["Modèle B2G", "Téléversement web direct vers l''USP, ou le réseau Peppol à quatre coins"], ["Modèle B2B", "Échange bilatéral volontaire, généralement via Peppol"], ["Déclaration en temps réel", "Aucune aujourd''hui — l''Autriche n''a pas de régime national de validation préalable ou de CTC"], ["SAF-T", "Un système sur demande existe depuis 2009 ; un « relancement » signalé en 2024 vers une déclaration périodique reste non confirmé mi-2026"]]', 'Comme pour les Pays-Bas, il n''y a ici aucun modèle de validation préalable à décrire pour le B2B — les factures circulent directement entre partenaires commerciaux, un contraste délibéré avec la Belgique, la France, l''Italie et la Pologne.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Canales', '[["Carga web USP", "Envío manual en formato ebInterface a través de erechnung.gv.at"], ["Red Peppol", "El canal recomendado para proveedores con capacidad transfronteriza"], ["EDIAKT II", "Canal EDI heredado para grandes proveedores con conexiones preexistentes"], ["Alcance", "Todos los Bundesbehörden (organismos federales); varios Länder, incluidos Viena, Baja Austria y Alta Austria, han adoptado sus propios requisitos comparables"]]', 'Las empresas deben comprobar si el organismo público concreto al que facturan es un organismo federal (cubierto a nivel nacional desde 2014/2018) o está sujeto a las normas propias, adoptadas por separado, de uno de los Länder.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kanäle', '[["USP-Web-Upload", "Manuelle Übermittlung im ebInterface-Format über erechnung.gv.at"], ["Peppol-Netzwerk", "Der empfohlene Kanal für grenzüberschreitend fähige Lieferanten"], ["EDIAKT II", "Legacy-EDI-Kanal für Großlieferanten mit bestehenden Verbindungen"], ["Umfang", "Alle Bundesbehörden; mehrere Länder, darunter Wien, Niederösterreich und Oberösterreich, haben eigene vergleichbare Anforderungen eingeführt"]]', 'Unternehmen sollten prüfen, ob die konkrete öffentliche Stelle, an die sie fakturieren, eine Bundesbehörde ist (bundesweit seit 2014/2018 abgedeckt) oder unter die eigenen, separat verabschiedeten Regeln eines Landes fällt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Canaux', '[["Téléversement web USP", "Soumission manuelle au format ebInterface via erechnung.gv.at"], ["Réseau Peppol", "Le canal recommandé pour les fournisseurs à capacité transfrontalière"], ["EDIAKT II", "Canal EDI hérité pour les gros fournisseurs disposant de connexions préexistantes"], ["Périmètre", "Tous les Bundesbehörden (organismes fédéraux) ; plusieurs Länder, dont Vienne, la Basse-Autriche et la Haute-Autriche, ont adopté leurs propres exigences comparables"]]', 'Les entreprises doivent vérifier si l''organisme public spécifique auquel elles facturent est un organisme fédéral (couvert nationalement depuis 2014/2018) ou relève des règles propres, adoptées séparément, de l''un des Länder.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'La decisión nacional pendiente', '[["Estado actual", "B2B voluntario; sin mandato nacional ni régimen de reporte en tiempo real"], ["Señal del BMF", "Un mandato nacional basado en Peppol, siguiendo el ejemplo de Bélgica y los Países Bajos"], ["Propuesta formal", "Esperada para el 3.º trimestre de 2026 — aún no publicada a principios de agosto de 2026"], ["Suelo firme en cualquier caso", "1 de julio de 2030 — B2B transfronterizo de ViDA, derecho de la UE confirmado"]]', 'Esta es la única entrada de esta página que está genuinamente por decidir — siga la página de fuentes y el panel del rastreador para conocer la propuesta formal del BMF una vez publicada, ya que determinará el alcance y el calendario de cualquier requisito B2B nacional.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Die ausstehende inländische Entscheidung', '[["Aktueller Status", "B2B freiwillig; keine inländische Pflicht oder Echtzeit-Meldepflicht"], ["BMF-Signal", "Eine inländische Pflicht auf Peppol-Basis, analog zu Belgien und den Niederlanden"], ["Formeller Vorschlag", "Erwartet im 3. Quartal 2026 — Anfang August 2026 noch nicht veröffentlicht"], ["Feste Untergrenze in jedem Fall", "1. Juli 2030 — grenzüberschreitendes B2B nach ViDA, bestätigtes EU-Recht"]]', 'Dies ist der einzige Eintrag auf dieser Seite, der wirklich noch offen ist — verfolgen Sie die Quellenseite und die Tracker-Tafel auf den formellen Vorschlag des BMF, sobald er veröffentlicht wird, denn er wird Umfang und Zeitplan einer etwaigen inländischen B2B-Anforderung bestimmen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'La décision nationale en attente', '[["Statut actuel", "B2B volontaire ; aucune obligation nationale ni régime de déclaration en temps réel"], ["Signal du BMF", "Une obligation nationale basée sur Peppol, à l''instar de la Belgique et des Pays-Bas"], ["Proposition formelle", "Attendue au 3ᵉ trimestre 2026 — non encore publiée début août 2026"], ["Plancher ferme dans tous les cas", "1er juillet 2030 — B2B transfrontalier ViDA, droit de l''UE confirmé"]]', 'C''est la seule entrée de cette page qui soit véritablement indécise — suivez la page des sources et le tableau du tracker pour la proposition formelle du BMF une fois publiée, car elle déterminera le périmètre et le calendrier de toute exigence B2B nationale.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚖️ Rechazo B2G', NULL, NULL, 'Las facturas no conformes a organismos federales austriacos se enfrentan al rechazo bajo los requisitos de formato del USP — lo más parecido a la aplicación que existe hoy, y limitado al comercio con el gobierno más que a la economía en general.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚖️ B2G-Ablehnung', NULL, NULL, 'Nicht konforme Rechnungen an österreichische Bundesbehörden werden im Rahmen der Formatanforderungen des USP abgelehnt — der einzige heute existierende Durchsetzungsmechanismus, beschränkt auf den Handel mit dem Staat statt auf die gesamte Wirtschaft.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚖️ Rejet B2G', NULL, NULL, 'Les factures non conformes aux organismes fédéraux autrichiens s''exposent à un rejet selon les exigences de format de l''USP — le mécanisme le plus proche d''une application existant aujourd''hui, limité au commerce avec l''État plutôt qu''à l''ensemble de l''économie.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🤝 Aún no hay régimen sancionador B2B nacional', NULL, NULL, 'No existe una sanción legal por incumplimiento B2B hoy, porque no existe una obligación legal B2B. En la práctica, las empresas adoptan Peppol o ebInterface de forma voluntaria para seguir siendo interoperables con socios comerciales de la UE ya sujetos a regímenes obligatorios en otros lugares.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🤝 Noch kein inländisches B2B-Sanktionsregime', NULL, NULL, 'Es gibt heute keine gesetzliche Strafe für B2B-Nichteinhaltung, weil es keine gesetzliche B2B-Pflicht gibt. In der Praxis übernehmen Unternehmen Peppol oder ebInterface freiwillig, um mit EU-Handelspartnern interoperabel zu bleiben, die anderswo bereits verpflichtenden Regelungen unterliegen.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🤝 Pas encore de régime de sanctions B2B national', NULL, NULL, 'Il n''existe aujourd''hui aucune sanction légale pour non-conformité B2B, car il n''existe aucune obligation légale B2B. En pratique, les entreprises adoptent Peppol ou ebInterface volontairement pour rester interopérables avec des partenaires commerciaux européens déjà soumis à des régimes obligatoires ailleurs.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🇪🇺 El suelo de la UE que se acerca', NULL, NULL, 'Con independencia de lo que decida Austria a nivel nacional, el requisito transfronterizo de ViDA es derecho de la UE confirmado desde el 1 de julio de 2030 — toda empresa austriaca que realice comercio B2B intracomunitario necesitará facturación electrónica y reporte digital conformes con EN 16931 para esas operaciones, con o sin mandato.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🇪🇺 Die näherrückende EU-Untergrenze', NULL, NULL, 'Unabhängig davon, was Österreich innerstaatlich entscheidet, ist die grenzüberschreitende ViDA-Anforderung ab dem 1. Juli 2030 bestätigtes EU-Recht — jedes österreichische Unternehmen mit innergemeinschaftlichem B2B-Handel benötigt für diese Umsätze EN-16931-konforme E-Rechnung und digitale Meldung, Pflicht hin oder her.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🇪🇺 Le plancher de l''UE qui approche', NULL, NULL, 'Quelle que soit la décision de l''Autriche au niveau national, l''exigence transfrontalière de ViDA est un droit de l''UE confirmé à partir du 1er juillet 2030 — toute entreprise autrichienne réalisant du commerce B2B intracommunautaire aura besoin d''une facturation électronique et d''une déclaration numérique conformes à l''EN 16931 pour ces opérations, obligation ou non.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Austria' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme su capacidad ebInterface o Peppol', 'Compruebe si su ERP o software de contabilidad ya admite ebInterface (6.0/6.1) o Peppol BIS 3.0 — muchas plataformas habituales austriacas y de la UE admiten al menos una de forma nativa.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Austria' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie Ihre ebInterface- oder Peppol-Fähigkeit', 'Prüfen Sie, ob Ihr ERP- oder Buchhaltungssystem bereits ebInterface (6.0/6.1) oder Peppol BIS 3.0 unterstützt — viele gängige österreichische und EU-Plattformen unterstützen mindestens eines nativ.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Austria' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez votre capacité ebInterface ou Peppol', 'Vérifiez si votre ERP ou logiciel comptable prend déjà en charge ebInterface (6.0/6.1) ou Peppol BIS 3.0 — de nombreuses plateformes autrichiennes et européennes courantes prennent en charge au moins l''un des deux nativement.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Austria' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Verifique su canal B2G si factura a organismos públicos austriacos', 'Confirme que está registrado a través del USP y que presenta correctamente, y compruebe si el organismo concreto al que factura es federal (cubierto desde 2014/2018) o está sujeto a un requisito propio, adoptado por separado, de un Land.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Austria' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Überprüfen Sie Ihren B2G-Kanal, falls Sie an österreichische öffentliche Stellen fakturieren', 'Bestätigen Sie, dass Sie über das USP registriert sind und korrekt übermitteln, und prüfen Sie, ob die konkrete Stelle, an die Sie fakturieren, eine Bundesbehörde ist (seit 2014/2018 abgedeckt) oder unter eine eigene, separat verabschiedete Anforderung eines Landes fällt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Austria' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez votre canal B2G si vous facturez des organismes publics autrichiens', 'Confirmez que vous êtes enregistré via l''USP et que vous soumettez correctement, et vérifiez si l''organisme spécifique auquel vous facturez est fédéral (couvert depuis 2014/2018) ou relève d''une exigence propre, adoptée séparément, d''un Land.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Austria' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Siga la propuesta B2B nacional del BMF', 'Esta es la pregunta abierta más importante para la facturación electrónica austriaca — la propuesta formal esperada para el tercer trimestre de 2026 determinará el alcance y el calendario de cualquier mandato B2B nacional.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Austria' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Verfolgen Sie den inländischen B2B-Vorschlag des BMF', 'Dies ist die wichtigste offene Frage für die österreichische E-Rechnung — der für das dritte Quartal 2026 erwartete formelle Vorschlag wird Umfang und Zeitplan einer etwaigen inländischen B2B-Pflicht bestimmen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Austria' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Suivez la proposition B2B nationale du BMF', 'C''est la question ouverte la plus déterminante pour la facturation électronique autrichienne — la proposition formelle attendue au troisième trimestre 2026 déterminera le périmètre et le calendrier de toute obligation B2B nationale.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Austria' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Prepárese para el suelo transfronterizo de 2030 en cualquier caso', 'Incluso antes de que llegue cualquier mandato nacional, toda empresa que realice comercio B2B intracomunitario necesitará capacidad de facturación electrónica y reporte digital conforme a EN 16931 desde el 1 de julio de 2030 — esta fecha la fija la directiva de la UE, no la discreción austriaca.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Austria' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bereiten Sie sich in jedem Fall auf die grenzüberschreitende Untergrenze 2030 vor', 'Noch bevor eine inländische Pflicht kommt, benötigt jedes Unternehmen mit innergemeinschaftlichem B2B-Handel ab dem 1. Juli 2030 EN-16931-konforme E-Rechnungs- und digitale Meldefähigkeit — dieses Datum ist durch EU-Richtlinie festgelegt, nicht durch österreichisches Ermessen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Austria' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Préparez-vous au plancher transfrontalier de 2030 dans tous les cas', 'Même avant l''arrivée d''une éventuelle obligation nationale, toute entreprise réalisant du commerce B2B intracommunautaire aura besoin d''une capacité de facturation électronique et de déclaration numérique conforme à l''EN 16931 dès le 1er juillet 2030 — cette date est fixée par la directive de l''UE, non par la discrétion autrichienne.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Austria' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Esté atento a ebInterface 7.0', 'Prevista para el cuarto trimestre de 2026 con una vinculación formal de sintaxis a EN 16931 — no se ha anunciado ninguna migración obligatoria desde 6.0/6.1, pero vale la pena conocerla si usa ebInterface directamente en lugar de Peppol.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Austria' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Achten Sie auf ebInterface 7.0', 'Erwartet im vierten Quartal 2026 mit einer formalen Syntaxbindung an EN 16931 — ein verpflichtender Umstieg von 6.0/6.1 wurde nicht angekündigt, ist aber wissenswert, wenn Sie ebInterface direkt statt Peppol nutzen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Austria' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Surveillez ebInterface 7.0', 'Attendue au quatrième trimestre 2026 avec une liaison syntaxique formelle à l''EN 16931 — aucune migration obligatoire depuis la 6.0/6.1 n''a été annoncée, mais cela vaut la peine d''être connu si vous utilisez ebInterface directement plutôt que Peppol.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Austria' AND ds.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'e-Rechnung.gv.at (USP)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Austria' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'e-Rechnung.gv.at (USP)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Austria' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'e-Rechnung.gv.at (USP)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Austria' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'WKO — ebInterface' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Austria' AND dp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'WKO — ebInterface' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Austria' AND dp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'WKO — ebInterface' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Austria' AND dp.sort_order = 1;
